  console.log(status + ' ' + test.name + ': ' + result + ' (expected: ' + test.expected + ')');
  if (success) passed++;
  else failed++;
});

console.log('\n========================');
console.log('Passed: ' + passed + '/' + tests.length);
if (failed === 0) {
  console.log('All tests passed! ✓');
}
